function mm_find_user(array $d,int $id){foreach($d['users'] as $x)if((int)$x['id']===$id)return $x;return null;}
function mm_branch_name(array $d,$id){if(!$id)return 'AUTO / Nearest';foreach($d['branches']??[] as $b)if((int)$b['id']===(int)$id)return (string)$b['name'];return 'AUTO / Nearest';}
function mm_pr_avatar(array $p){$rel=(string)($p['profile']['profile_photo']??'');if($rel==='')return '';if(strpos($rel,'storage/pr-media/')===0)return 'pr-media.php?pr_id='.(int)$p['id'].'&field=profile_photo';return $rel;}
function mm_next_shift(array $d,int $prId){$today=date('Y-m-d');$rows=[];foreach($d['shifts']??[] as $s){if((int)($s['pr_id']??0)!==$prId)continue;if(in_array((string)($s['status']??'scheduled'),['cancelled','off'],true))continue;if((string)($s['date']??'')<$today)continue;$rows[]=$s;}usort($rows,function($a,$b){return strcmp((string)($a['date']??'').($a['start']??''),(string)($b['date']??'').($b['start']??''));});return $rows?$rows[0]:null;}
function mm_open_jobs(array $d,int $prId){$n=0;foreach($d['checkins']??[] as $c)if((int)($c['pr_id']??0)===$prId&&!in_array((string)($c['status']??''),['completed','cancelled','rejected'],true))$n++;return $n;}
